    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            arr[i] = (long) in.nval;
        }
        in.nextToken();
        int r = (int) in.nval;
        in.nextToken();
        int c = (int) in.nval;
        long[][] matrix = new long[r][c];
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++) {
                in.nextToken();
                matrix[i][j] = (long) in.nval;
            }
        long[][] freq = frequencies(arr);
        StringBuilder sb = new StringBuilder();
        sb.append(freq.length).append("\n");
        for (long[] p : freq) sb.append(p[0]).append(" ").append(p[1]).append("\n");
        for (long[] row : transpose(matrix)) {
            for (int j = 0; j < row.length; j++) sb.append(row[j]).append(j + 1 < row.length ? " " : "\n");
        }
        System.out.print(sb);
    }
}
